<?php
if (!defined('ABSPATH')) { exit; }
final class SC_Library_Runtime_Certification { public const VERSION='6.2.0'; public function register_hooks():void { add_action('rest_api_init',[$this,'register_rest']); add_shortcode('sc_library_runtime_certification',[$this,'shortcode']); } public function register_rest():void { register_rest_route('sc-library/v1','/runtime-certification',['methods'=>WP_REST_Server::READABLE,'permission_callback'=>'__return_true','callback'=>[$this,'status']]); } public function status():array { return ['schema'=>'sc-library-wordpress-runtime-certification-adapter/1.0','library_version'=>SC_LIBRARY_VERSION,'wordpress_role'=>'optional-thin-adapter','authoritative'=>false,'backend_endpoint'=>'/api/library/v1/runtime-certification/readiness']; } public function shortcode():string { return '<div class="sc-library-runtime-certification">Library runtime certification is backend-authoritative; WordPress is optional.</div>'; } }
